(4160297, 597972, 84363, '<td valign="top">These is absolutley no definition on the birds.  The geese are completley blown-out and lost.</td>', 'These is absolutley no definition on the birds.  The geese are completley blown-out and lost.', '2007-10-11 13:40:28.000000', NULL, 1),
(4160299, 597954, 84363, '<td valign="top">Is he wild or a pet?</td>', 'Is he wild or a pet?', '2007-10-11 13:40:59.000000', NULL, 1),
(4160301, 598244, 84363, '<td valign="top">Very nice expression and capture!!!</td>', 'Very nice expression and capture!!!', '2007-10-11 13:41:22.000000', NULL, 1),
(4160366, 598419, 12733, '<td valign="top">The rubber duckie is in much sharper focus than the gulls, and that doesn''t really work. Which one is Seymour, the gull walking away or the duckie???</td>', 'The rubber duckie is in much sharper focus than the gulls, and that doesn''t really work. Which one is Seymour, the gull walking away or the duckie???', '2007-10-11 14:19:28.000000', NULL, 1),
(4160370, 595592, 12733, '<td valign="top">Very cute.</td>', 'Very cute.', '2007-10-11 14:20:17.000000', NULL, 1),
(4160374, 596178, 12733, '<td valign="top">Very strong emotional content. Who said animals don''t have human-like feelings?</td>', 'Very strong emotional content. Who said animals don''t have human-like feelings?', '2007-10-11 14:21:43.000000', NULL, 1),
(4160377, 598244, 12733, '<td valign="top">The look of being ready to fight! I think if I got that look I''d split, rather than taking a picture. Great shot.</td>', 'The look of being ready to fight! I think if I got that look I''d split, rather than taking a picture. Great shot.', '2007-10-11 14:23:19.000000', NULL, 1),
(4160386, 597434, 12733, '<td valign="top">A very cute pig. Does he have a spider to protect him? I''m not sure how you could find an angle to do this, but the picture would be better without the partial pigs in the background.</td>', 'A very cute pig. Does he have a spider to protect him? I''m not sure how you could find an angle to do this, but the picture would be better without the partial pigs in the background.', '2007-10-11 14:26:41.000000', NULL, 1),
(4160388, 598389, 85258, '<td valign="top">Would love to see this in B/W!</td>', 'Would love to see this in B/W!', '2007-10-11 14:26:50.000000', NULL, 1),
(4160518, 598417, 69368, '<td valign="top">Could this be a toy-elephant? <br/>The wrinkles on his nose are very deep, his eye is too large and his ear looks as if it was sticked to the head....<br/>You almost fooled me</td>', 'Could this be a toy-elephant? The wrinkles on his nose are very deep, his eye is too large and his ear looks as if it was sticked to the head....You almost fooled me', '2007-10-11 15:16:36.000000', NULL, 1),
(4160551, 598033, 68586, '<td valign="top">Really nice image</td>', 'Really nice image', '2007-10-11 15:25:26.000000', NULL, 1),
(4160558, 598279, 68586, '<td valign="top">Very nice image</td>', 'Very nice image', '2007-10-11 15:26:29.000000', NULL, 1),
(4160563, 598086, 68586, '<td valign="top">A truly outstanding image that deserves to ribbon.</td>', 'A truly outstanding image that deserves to ribbon.', '2007-10-11 15:27:42.000000', NULL, 1),
(4160567, 597014, 68586, '<td valign="top">I really like the strength of this image. Almost classical in it''s simplicity.</td>', 'I really like the strength of this image. Almost classical in it''s simplicity.', '2007-10-11 15:28:46.000000', NULL, 1),
(4160568, 598013, 68586, '<td valign="top">What a great looking little fella  :- )</td>', 'What a great looking little fella  :- )', '2007-10-11 15:29:07.000000', NULL, 1),
(4160725, 598417, 84339, '<td valign="top">Nice focus on the eye</td>', 'Nice focus on the eye', '2007-10-11 16:17:45.000000', NULL, 1),
(4160730, 596551, 84339, '<td valign="top">Nice facial expression on the cat. You might have cropped it a little more but really nice shot.</td>', 'Nice facial expression on the cat. You might have cropped it a little more but really nice shot.', '2007-10-11 16:19:34.000000', NULL, 1),
(4160731, 598144, 84339, '<td valign="top">Nice composition</td>', 'Nice composition', '2007-10-11 16:19:49.000000', NULL, 1),
(4160736, 597275, 84339, '<td valign="top">Im glad to see a human in the mix but a more nature oriented setting would have been nice.</td>', 'Im glad to see a human in the mix but a more nature oriented setting would have been nice.', '2007-10-11 16:21:30.000000', NULL, 1),
(4160741, 597933, 84339, '<td valign="top">Glad to see a human in the mix. Shot is a little soft. Love the natural setting. Possibly a less portraitish pose and a more animal like pose would work better.</td>', 'Glad to see a human in the mix. Shot is a little soft. Love the natural setting. Possibly a less portraitish pose and a more animal like pose would work better.', '2007-10-11 16:23:23.000000', NULL, 1),
(4160744, 597692, 84339, '<td valign="top">A bit blurry but cute :)</td>', 'A bit blurry but cute :)', '2007-10-11 16:23:52.000000', NULL, 1),
(4160815, 597451, 79720, '<td valign="top">I wonder how this might look with a tighter, portrait crop.</td>', 'I wonder how this might look with a tighter, portrait crop.', '2007-10-11 16:57:27.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4160818, 595928, 79720, '<td valign="top">Very nice monochrome conversion.</td>', 'Very nice monochrome conversion.', '2007-10-11 16:57:44.000000', NULL, 1),
(4160819, 597314, 79720, '<td valign="top">I''m sure you''ve already had some comments about the missing antler tips, so I''ll save it. Nice capture and bokeh.</td>', 'I''m sure you''ve already had some comments about the missing antler tips, so I''ll save it. Nice capture and bokeh.', '2007-10-11 16:58:37.000000', NULL, 1),
(4160821, 597626, 79720, '<td valign="top">haha! Very nice capture. The aberrations around his fur kind of ruin the image, but cute none-the-less.</td>', 'haha! Very nice capture. The aberrations around his fur kind of ruin the image, but cute none-the-less.', '2007-10-11 16:59:38.000000', NULL, 1),
(4160824, 598013, 79720, '<td valign="top">Great macro. Did you try a higher saturation level on post-processing?</td>', 'Great macro. Did you try a higher saturation level on post-processing?', '2007-10-11 17:00:53.000000', NULL, 1),
(4160826, 596146, 79720, '<td valign="top">Tough, tough subject. Well captured.</td>', 'Tough, tough subject. Well captured.', '2007-10-11 17:01:15.000000', NULL, 1),
(4160829, 598033, 39675, '<td valign="top">This is a nice shot.  I think the colors worked out well.  I hope you keep participating from time to time even though class is over.</td>', 'This is a nice shot.  I think the colors worked out well.  I hope you keep participating from time to time even though class is over.', '2007-10-11 17:02:06.000000', NULL, 1),
(4160837, 595599, 79720, '<td valign="top">Lost a little detail in the birds feathers, maybe from softening the focus or noise reduction.</td>', 'Lost a little detail in the birds feathers, maybe from softening the focus or noise reduction.', '2007-10-11 17:05:31.000000', NULL, 1),
(4160840, 598417, 39675, '<td valign="top">This is a nice shot of a REAL LIFE elephant.  The focus is so sharp I can almost see the elephant breathing.  You know what they say about elephants... They never forget!  This elephant looks very intelligent.  I might say bright even.  Almost like a candle...</td>', 'This is a nice shot of a REAL LIFE elephant.  The focus is so sharp I can almost see the elephant breathing.  You know what they say about elephants... They never forget!  This elephant looks very intelligent.  I might say bright even.  Almost like a candle...', '2007-10-11 17:06:11.000000', NULL, 1),
(4160842, 598189, 79720, '<td valign="top">Very impressive for an underwater capture.</td>', 'Very impressive for an underwater capture.', '2007-10-11 17:06:30.000000', NULL, 1),
(4160844, 598263, 79720, '<td valign="top">I think this image loses something by resizing so small. There doesn''t appear to be enough colour contrast between the flower and the butterfly. However, it is well-composed.</td>', 'I think this image loses something by resizing so small. There doesn''t appear to be enough colour contrast between the flower and the butterfly. However, it is well-composed.', '2007-10-11 17:07:43.000000', NULL, 1),
(4160846, 597936, 79720, '<td valign="top">Now that''s close. Very interesting image.</td>', 'Now that''s close. Very interesting image.', '2007-10-11 17:08:21.000000', NULL, 1),
(4160849, 595963, 79720, '<td valign="top">This image seems to have lost some contrast with the B&amp;W processing. You''ve lost a lot of tonal range, depending on the camera you were using.</td>', 'This image seems to have lost some contrast with the B&W processing. You''ve lost a lot of tonal range, depending on the camera you were using.', '2007-10-11 17:09:29.000000', NULL, 1),
(4160850, 597625, 79720, '<td valign="top">lol, nice title.</td>', 'lol, nice title.', '2007-10-11 17:09:49.000000', NULL, 1),
(4160852, 598169, 79720, '<td valign="top">Yikes, disturbing image. Well captured, just not my cup of tea.</td>', 'Yikes, disturbing image. Well captured, just not my cup of tea.', '2007-10-11 17:10:35.000000', NULL, 1),
(4160856, 595911, 79720, '<td valign="top">The lighting seems to have been iffy, leading to a soft image with too little contrast in the colours.</td>', 'The lighting seems to have been iffy, leading to a soft image with too little contrast in the colours.', '2007-10-11 17:12:07.000000', NULL, 1),
(4160860, 597933, 79720, '<td valign="top">Yes, we are. This does seem a touch contrived, and her over-the-shoulder glance pose makes her neck seems too wide for her head. The natural light is nice, but in this case it''s falling from behind the model, not properly highlighting her face.</td>', 'Yes, we are. This does seem a touch contrived, and her over-the-shoulder glance pose makes her neck seems too wide for her head. The natural light is nice, but in this case it''s falling from behind the model, not properly highlighting her face.', '2007-10-11 17:14:13.000000', NULL, 1),
(4160862, 597919, 79720, '<td valign="top">Nice shallow DoF. Good composition.</td>', 'Nice shallow DoF. Good composition.', '2007-10-11 17:14:43.000000', NULL, 1),
(4160863, 596459, 79720, '<td valign="top">Tough subject. Seems a bit out of focus, and the natural light is too strong.</td>', 'Tough subject. Seems a bit out of focus, and the natural light is too strong.', '2007-10-11 17:15:44.000000', NULL, 1),
(4160866, 598061, 79720, '<td valign="top">The road behind the deer is very distracting, and the colour seems flat.</td>', 'The road behind the deer is very distracting, and the colour seems flat.', '2007-10-11 17:18:22.000000', NULL, 1),
(4160868, 597358, 79720, '<td valign="top">Now that is a shallow DoF. Seems to be a bit of haloing resulting from your post-process routine.</td>', 'Now that is a shallow DoF. Seems to be a bit of haloing resulting from your post-process routine.', '2007-10-11 17:19:14.000000', NULL, 1),
(4160874, 598265, 79720, '<td valign="top">Pray? It''s a religious hawk? I think you meant "prey".</td>', 'Pray? It''s a religious hawk? I think you meant "prey".', '2007-10-11 17:19:59.000000', NULL, 1),
(4160877, 595170, 79720, '<td valign="top">I think you may have oversharpened this one...</td>', 'I think you may have oversharpened this one...', '2007-10-11 17:21:47.000000', NULL, 1),
(4160880, 597371, 79720, '<td valign="top">Lovely DoF and bokeh, very nice composition.</td>', 'Lovely DoF and bokeh, very nice composition.', '2007-10-11 17:23:23.000000', NULL, 1),
(4160885, 597851, 79720, '<td valign="top">Nice use of wide angle, but I think the filesize limit may have hurt the sharpeness of the image.</td>', 'Nice use of wide angle, but I think the filesize limit may have hurt the sharpeness of the image.', '2007-10-11 17:25:33.000000', NULL, 1),
(4160888, 598018, 79720, '<td valign="top">Nice cropping!</td>', 'Nice cropping!', '2007-10-11 17:26:39.000000', NULL, 1),
(4160891, 595927, 79720, '<td valign="top">Whoops! Wrong challenge. Still a nice image, but I''m sure everyone has already posted !DNMC! at you. <b>:</b>-(</td>', 'Whoops! Wrong challenge. Still a nice image, but I''m sure everyone has already posted !DNMC! at you. :-(', '2007-10-11 17:27:54.000000', NULL, 1),
(4160902, 597329, 83313, '<td valign="top">The mantis really stands out against the stark white background. This has to be one of the most fascinating looking insects around. (Along with dragonflies)</td>', 'The mantis really stands out against the stark white background. This has to be one of the most fascinating looking insects around. (Along with dragonflies)', '2007-10-11 17:30:34.000000', NULL, 1),
(4160905, 597042, 79720, '<td valign="top">Oh, those wacky lemurs.</td>', 'Oh, those wacky lemurs.', '2007-10-11 17:31:31.000000', NULL, 1),
(4160907, 596109, 83313, '<td valign="top">Good use of shadows to portray hurt.  Detail looks a little blown out on the far right, though.</td>', 'Good use of shadows to portray hurt.  Detail looks a little blown out on the far right, though.', '2007-10-11 17:32:08.000000', NULL, 1),
(4160910, 598388, 79720, '<td valign="top">Nice duotone conversion.</td>', 'Nice duotone conversion.', '2007-10-11 17:32:32.000000', NULL, 1),
(4160911, 597503, 83313, '<td valign="top">Nice backgorund and detail.</td>', 'Nice backgorund and detail.', '2007-10-11 17:32:44.000000', NULL, 1),
(4160921, 598226, 83313, '<td valign="top">Composition seems a little too centered for me. The bill seems mildly out of focus. A touch stronger on the colors might give this guy some oomph.</td>', 'Composition seems a little too centered for me. The bill seems mildly out of focus. A touch stronger on the colors might give this guy some oomph.', '2007-10-11 17:35:46.000000', NULL, 1),
(4160923, 598140, 83313, '<td valign="top">Crisp and colorful.</td>', 'Crisp and colorful.', '2007-10-11 17:36:07.000000', NULL, 1),
(4160925, 595099, 79720, '<td valign="top">I''m quite sure there are a number of comments already, so at the risk of repeating any criticism, the image has lost a lot in your post-processing routine.</td>', 'I''m quite sure there are a number of comments already, so at the risk of repeating any criticism, the image has lost a lot in your post-processing routine.', '2007-10-11 17:36:22.000000', NULL, 1),
(4160935, 595099, 83313, '<td valign="top">Sorry to be so harsh, but I''m betting this image for last place ribbon. Blurry, low resolution, blown out highlights, shadows blend into background. Snapshottish in appearance.</td>', 'Sorry to be so harsh, but I''m betting this image for last place ribbon. Blurry, low resolution, blown out highlights, shadows blend into background. Snapshottish in appearance.', '2007-10-11 17:39:10.000000', NULL, 1),
(4160936, 596219, 79720, '<td valign="top">Sabieri, must be. Nice shallow DoF, and some beautiful post-processing.</td>', 'Sabieri, must be. Nice shallow DoF, and some beautiful post-processing.', '2007-10-11 17:39:14.000000', NULL, 1),
(4160940, 597629, 79720, '<td valign="top">haha! Too bad I saw this one second.</td>', 'haha! Too bad I saw this one second.', '2007-10-11 17:39:48.000000', NULL, 1),
(4160941, 596080, 83313, '<td valign="top">Wow! A lot of impact. Love the eyes.</td>', 'Wow! A lot of impact. Love the eyes.', '2007-10-11 17:39:57.000000', NULL, 1),
(4160942, 598225, 83313, '<td valign="top">A decent shot, but verycentered and details in his fur appear a touch over-enhanced.</td>', 'A decent shot, but verycentered and details in his fur appear a touch over-enhanced.', '2007-10-11 17:40:46.000000', NULL, 1),
(4160943, 595483, 79720, '<td valign="top">uh-oh. Timestamps are a no-no.</td>', 'uh-oh. Timestamps are a no-no.', '2007-10-11 17:41:20.000000', NULL, 1),
(4160974, 597600, 84630, '<td valign="top">Awesome photo</td>', 'Awesome photo', '2007-10-11 18:04:05.000000', NULL, 1),
(4160985, 597275, 44151, '<td valign="top">Where''s the fauna?</td>', 'Where''s the fauna?', '2007-10-11 18:07:30.000000', NULL, 1),
(4161011, 597371, 68178, '<td valign="top">Perfect colors, I like how the birds colors match the leaves in the backround.</td>', 'Perfect colors, I like how the birds colors match the leaves in the backround.', '2007-10-11 18:17:51.000000', NULL, 1),
(4161015, 596402, 68178, '<td valign="top">Nice find. These are hard birds to spot (for obvious reasons).</td>', 'Nice find. These are hard birds to spot (for obvious reasons).', '2007-10-11 18:18:33.000000', NULL, 1),
(4161017, 596037, 68178, '<td valign="top">Tones are spot on, composition is excellent. Bumping after a closer look.</td>', 'Tones are spot on, composition is excellent. Bumping after a closer look.', '2007-10-11 18:19:18.000000', NULL, 1),
(4161043, 595990, 68178, '<td valign="top">Neat! The blue conversion left some noise in the water (may be my uncalibrated monitor) but didn''t knock it down any.</td>', 'Neat! The blue conversion left some noise in the water (may be my uncalibrated monitor) but didn''t knock it down any.', '2007-10-11 18:28:17.000000', NULL, 1),
(4161045, 598169, 68178, '<td valign="top">Gory heh. Neat though. One of the funnest times I had at the zoo was at snake feeding time :p</td>', 'Gory heh. Neat though. One of the funnest times I had at the zoo was at snake feeding time :p', '2007-10-11 18:29:05.000000', NULL, 1),
(4161046, 597293, 68178, '<td valign="top">Perfect colors and clarity. Well done!</td>', 'Perfect colors and clarity. Well done!', '2007-10-11 18:29:35.000000', NULL, 1),
(4161049, 598417, 68178, '<td valign="top">I love the tones and textures here. The DOF and distortion give it an added character that I like. Bumping after a closer look.</td>', 'I love the tones and textures here. The DOF and distortion give it an added character that I like. Bumping after a closer look.', '2007-10-11 18:30:39.000000', NULL, 1),
(4161050, 598038, 68178, '<td valign="top">Almost daydreaming. Very cool shot.</td>', 'Almost daydreaming. Very cool shot.', '2007-10-11 18:31:18.000000', NULL, 1),
(4161051, 598317, 68178, '<td valign="top">Nice capture. It almost looks annoyed :p</td>', 'Nice capture. It almost looks annoyed :p', '2007-10-11 18:32:18.000000', NULL, 1),
(4161054, 597513, 68178, '<td valign="top">Excellent tone ranges and light! The eye grabs your attention right off. Well done!</td>', 'Excellent tone ranges and light! The eye grabs your attention right off. Well done!', '2007-10-11 18:33:32.000000', NULL, 1),
(4161056, 596178, 68178, '<td valign="top">Love the brown tones! They almost have a human quality.</td>', 'Love the brown tones! They almost have a human quality.', '2007-10-11 18:34:20.000000', NULL, 1),
(4161060, 598309, 68178, '<td valign="top">Neat crane. The contrast is a tad mute, though probably a product of the fog.</td>', 'Neat crane. The contrast is a tad mute, though probably a product of the fog.', '2007-10-11 18:35:40.000000', NULL, 1),
(4161063, 595562, 68178, '<td valign="top">Love the detail with all the little water droplet. One of the best duck pictures this challenge for sure!</td>', 'Love the detail with all the little water droplet. One of the best duck pictures this challenge for sure!', '2007-10-11 18:36:36.000000', NULL, 1),
(4161068, 598189, 68178, '<td valign="top">This is great! A difficult critter to photograph for sure.</td>', 'This is great! A difficult critter to photograph for sure.', '2007-10-11 18:37:38.000000', NULL, 1),
(4161071, 598410, 68178, '<td valign="top">This would be a great greeting card (or caption contest) picture :p Nice job making the personality come through!</td>', 'This would be a great greeting card (or caption contest) picture :p Nice job making the personality come through!', '2007-10-11 18:38:28.000000', NULL, 1),
(4161073, 596088, 68178, '<td valign="top">Excellent detail! Even down the the spot in the eye. Well done.</td>', 'Excellent detail! Even down the the spot in the eye. Well done.', '2007-10-11 18:39:14.000000', NULL, 1),
(4161077, 597642, 68178, '<td valign="top">I like the colors on this one. Seems so foreign in a way (I''m way landlocked). Well done.</td>', 'I like the colors on this one. Seems so foreign in a way (I''m way landlocked). Well done.', '2007-10-11 18:41:24.000000', NULL, 1),
(4161080, 597560, 68178, '<td valign="top">The picture is neat, but bonus points for the title. Got a chuckle out of me :p</td>', 'The picture is neat, but bonus points for the title. Got a chuckle out of me :p', '2007-10-11 18:41:58.000000', NULL, 1),
(4161082, 598165, 68178, '<td valign="top">I like the colors and composition. Only minor complaint is the power lines that you couldn''t do anything about in basic editing :p</td>', 'I like the colors and composition. Only minor complaint is the power lines that you couldn''t do anything about in basic editing :p', '2007-10-11 18:43:04.000000', NULL, 1),
(4161088, 596724, 68178, '<td valign="top">I love the motion. Might be a tad over saturated in the red.</td>', 'I love the motion. Might be a tad over saturated in the red.', '2007-10-11 18:43:58.000000', NULL, 1),
(4161091, 595365, 68178, '<td valign="top">Holy detail, Batman! (nice colors too!)</td>', 'Holy detail, Batman! (nice colors too!)', '2007-10-11 18:44:23.000000', NULL, 1),
(4161094, 596632, 68178, '<td valign="top">Thats pretty cool. The detail is spot on, particularly in the legs.</td>', 'Thats pretty cool. The detail is spot on, particularly in the legs.', '2007-10-11 18:45:09.000000', NULL, 1),
(4161097, 596146, 68178, '<td valign="top">I love clown fish! I miss mine :(</td>', 'I love clown fish! I miss mine :(', '2007-10-11 18:45:36.000000', NULL, 1),
(4161129, 597692, 44628, '<td valign="top">It has possibilities, but it''s blurry</td>', 'It has possibilities, but it''s blurry', '2007-10-11 18:59:47.000000', NULL, 1),
(4161133, 595099, 44628, '<td valign="top">Poor lighting and out of focus.</td>', 'Poor lighting and out of focus.', '2007-10-11 19:02:15.000000', NULL, 1),
(4161142, 596578, 44628, '<td valign="top">I love your caption!!</td>', 'I love your caption!!', '2007-10-11 19:07:30.000000', NULL, 1),
