(4162236, 596522, 65811, '<td valign="top">Hmm, Monitor Lizard?  He looks like a true-to-life dinosaur.  Focus seems a little soft, but I like the lighting.  I also like the blades of grass in his face -- makes the picture feel more "wild".</td>', 'Hmm, Monitor Lizard?  He looks like a true-to-life dinosaur.  Focus seems a little soft, but I like the lighting.  I also like the blades of grass in his face -- makes the picture feel more "wild".', '2007-10-12 08:21:49.000000', NULL, 1),
(4162239, 597935, 65811, '<td valign="top">I bet this guy took flight right after you shot this.  Not an easy shot to get.  I recommend boosting the Saturation levels, just to bring out all the colors :).</td>', 'I bet this guy took flight right after you shot this.  Not an easy shot to get.  I recommend boosting the Saturation levels, just to bring out all the colors :).', '2007-10-12 08:24:16.000000', NULL, 1),
(4162242, 597042, 65811, '<td valign="top">LOL  I love this pose!  The dude on the top seems a little lude ;).  The composition is perfect, lighting/colors - great.  Enjoy the ribbon, it''s well deserved.</td>', 'LOL  I love this pose!  The dude on the top seems a little lude ;).  The composition is perfect, lighting/colors - great.  Enjoy the ribbon, it''s well deserved.', '2007-10-12 08:26:44.000000', NULL, 1),
(4162247, 595365, 65811, '<td valign="top">I let out an audible gasp at the sight of this.  Beautiful.  Stunning detail.  Enjoy your ribbon.  This is gorgeous.</td>', 'I let out an audible gasp at the sight of this.  Beautiful.  Stunning detail.  Enjoy your ribbon.  This is gorgeous.', '2007-10-12 08:30:27.000000', NULL, 1),
(4162271, 597150, 43070, '<td valign="top">Too much distraction from the subject of the photo... several things distracting from it.. the neck of the rear dino going through the head of the subject.. the bright lit room in the back.. the red triangle on the top.. exposure was not set for the subject, losing feet to the base... a step to the left or right and a tighter cropping of the subject would have done wonders for the shot... worth anther visit... the red light on the bones could be a cool thing...</td>', 'Too much distraction from the subject of the photo... several things distracting from it.. the neck of the rear dino going through the head of the subject.. the bright lit room in the back.. the red triangle on the top.. exposure was not set for the subject, losing feet to the base... a step to the left or right and a tighter cropping of the subject would have done wonders for the shot... worth anther visit... the red light on the bones could be a cool thing...', '2007-10-12 08:58:02.000000', NULL, 1),
(4162273, 597279, 43070, '<td valign="top">excellent focus and color contrast between subject and background... i like it...</td>', 'excellent focus and color contrast between subject and background... i like it...', '2007-10-12 09:00:19.000000', NULL, 1),
