(4164488, 596037, 49969, '<td valign="top">You made a mundane scene look great. Keep it up!</td>', 'You made a mundane scene look great. Keep it up!', '2007-10-13 09:12:29.000000', NULL, 1),
(4164490, 597629, 49969, '<td valign="top">Very interesting subjects but the composition is quite awkward...</td>', 'Very interesting subjects but the composition is quite awkward...', '2007-10-13 09:13:49.000000', NULL, 1),
(4164492, 598263, 49969, '<td valign="top">A nice shot, but i''d prefer a bigger image.</td>', 'A nice shot, but i''d prefer a bigger image.', '2007-10-13 09:15:43.000000', NULL, 1),
(4164493, 597275, 82503, '<td valign="top">This is not really what I expect in a Fauna challenge.<br/> <br/>And by the way, it''s increasingly difficult to find something fundamental that sets us apart from the rest of the animals. Music certainly doesn''t count.</td>', 'This is not really what I expect in a Fauna challenge. And by the way, it''s increasingly difficult to find something fundamental that sets us apart from the rest of the animals. Music certainly doesn''t count.', '2007-10-13 09:16:38.000000', NULL, 1),
(4164496, 597625, 82503, '<td valign="top">Some people are not going to like this title. ;-) I think the image is really cute and the title is creative and well ... probably true...</td>', 'Some people are not going to like this title. ;-) I think the image is really cute and the title is creative and well ... probably true...', '2007-10-13 09:19:26.000000', NULL, 1),
(4164497, 597070, 49969, '<td valign="top">The composition could be improved.</td>', 'The composition could be improved.', '2007-10-13 09:19:41.000000', NULL, 1),
(4164498, 597929, 49969, '<td valign="top">The steam is just too distracting..</td>', 'The steam is just too distracting..', '2007-10-13 09:20:35.000000', NULL, 1),
(4164499, 595307, 49969, '<td valign="top">Not enough clarity in your focus.</td>', 'Not enough clarity in your focus.', '2007-10-13 09:20:59.000000', NULL, 1),
(4164501, 598021, 49969, '<td valign="top">Although this may not be "wildlife photography" in its orthodox sense, you managed to capture very exciting color combination in the red fins of the bass and the blue sky reflected in the water.</td>', 'Although this may not be "wildlife photography" in its orthodox sense, you managed to capture very exciting color combination in the red fins of the bass and the blue sky reflected in the water.', '2007-10-13 09:23:15.000000', NULL, 1),
(4164503, 597279, 49969, '<td valign="top">Very difficult shot well captured! My only complaint is that the focus is just slightly (given the size of your subject) off. Shots of insects, like shots of animals and humans, would usualy do best to focus on the eye(s).</td>', 'Very difficult shot well captured! My only complaint is that the focus is just slightly (given the size of your subject) off. Shots of insects, like shots of animals and humans, would usualy do best to focus on the eye(s).', '2007-10-13 09:24:57.000000', NULL, 1),
(4164504, 598169, 82503, '<td valign="top">Outch! Technically a great picture, I like the composition and the lighting. Very dramatic with the blood on the face. I''m curious to know how you set this up. As usual, you''ll probably get a bunch of low scores due to the unpleasant nature of the picture (especially if people think it''s a female victim and a male offender ;-) ).</td>', 'Outch! Technically a great picture, I like the composition and the lighting. Very dramatic with the blood on the face. I''m curious to know how you set this up. As usual, you''ll probably get a bunch of low scores due to the unpleasant nature of the picture (especially if people think it''s a female victim and a male offender ;-) ).', '2007-10-13 09:24:58.000000', NULL, 1),
(4164505, 596594, 49969, '<td valign="top">Very clear shot captured at just the right moment. It''d be even better if you gave your subject a little more "breathing space" in terms of framing.</td>', 'Very clear shot captured at just the right moment. It''d be even better if you gave your subject a little more "breathing space" in terms of framing.', '2007-10-13 09:27:41.000000', NULL, 1),
(4164508, 597293, 49969, '<td valign="top">Wow! Stunning colors! The diagonal branch makes excellent composition.</td>', 'Wow! Stunning colors! The diagonal branch makes excellent composition.', '2007-10-13 09:29:09.000000', NULL, 1),
(4164510, 596871, 49969, '<td valign="top">The lighting''s what gave this picture the magical "Babe" feel. Great job!</td>', 'The lighting''s what gave this picture the magical "Babe" feel. Great job!', '2007-10-13 09:32:03.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4164511, 596178, 82503, '<td valign="top">Oh, so sweet! The title is perfect, the kid really does look scared (or at least concerned) and the mum looks so unterstanding and calm. Great shot!</td>', 'Oh, so sweet! The title is perfect, the kid really does look scared (or at least concerned) and the mum looks so unterstanding and calm. Great shot!', '2007-10-13 09:33:33.000000', NULL, 1),
(4164512, 598150, 49969, '<td valign="top">Better color correction techniques would make this a great picture. And the focus would perhaps be better placed on the horse''s left eye. The moment''s very well captured. Keep up the good work!</td>', 'Better color correction techniques would make this a great picture. And the focus would perhaps be better placed on the horse''s left eye. The moment''s very well captured. Keep up the good work!', '2007-10-13 09:34:34.000000', NULL, 1),
(4164513, 596744, 49969, '<td valign="top">The composition could be improved by placing the snake''s head at one of the intersections of the thirds.</td>', 'The composition could be improved by placing the snake''s head at one of the intersections of the thirds.', '2007-10-13 09:37:12.000000', NULL, 1),
(4164514, 598086, 82503, '<td valign="top">Awesome picture! Something different. The drop makes it more interesting and adds a sense of scale. Composition and shallow DOF are great. One of my favorites in this challenge.</td>', 'Awesome picture! Something different. The drop makes it more interesting and adds a sense of scale. Composition and shallow DOF are great. One of my favorites in this challenge.', '2007-10-13 09:37:44.000000', NULL, 1),
(4164515, 597316, 82503, '<td valign="top">Lovely image, I like it a lot.</td>', 'Lovely image, I like it a lot.', '2007-10-13 09:38:57.000000', NULL, 1),
(4164516, 595927, 49969, '<td valign="top">Hmm... entered in the wrong category?</td>', 'Hmm... entered in the wrong category?', '2007-10-13 09:40:35.000000', NULL, 1),
(4164523, 596947, 34192, '<td valign="top">photographically speaking, the photo is okay (the depth of field is too large, the lighting is unremarkable, the composition is weak).  However, when looking at animals images (as opposed to flower images for instance), one must take into consideration things like opportunity and timing.  You had an amazing opportunity to capture something unique and your timing was excellent (replace these two with a couple of squirrels any you see my point).  My expectation of technicals is low with images such as this - the moment weighs much stronger - you don''t have time to worry about all the crap.  Hope other voters realize this, though I''m afraid they won''t.  But, on your ability to capture an amazing moment, I give you an 8.  Would love to read the story behind this opportunity.</td>', 'photographically speaking, the photo is okay (the depth of field is too large, the lighting is unremarkable, the composition is weak).  However, when looking at animals images (as opposed to flower images for instance), one must take into consideration things like opportunity and timing.  You had an amazing opportunity to capture something unique and your timing was excellent (replace these two with a couple of squirrels any you see my point).  My expectation of technicals is low with images such as this - the moment weighs much stronger - you don''t have time to worry about all the crap.  Hope other voters realize this, though I''m afraid they won''t.  But, on your ability to capture an amazing moment, I give you an 8.  Would love to read the story behind this opportunity.', '2007-10-13 09:44:49.000000', NULL, 1),
(4164564, 598086, 55822, '<td valign="top">Great detail in a very small critter.</td>', 'Great detail in a very small critter.', '2007-10-13 10:41:46.000000', NULL, 1),
(4164590, 595697, 30791, '<td valign="top">ooo pretty</td>', 'ooo pretty', '2007-10-13 11:12:04.000000', NULL, 1),
