(4166295, 598169, 23251, '<td valign="top">Well yeah clear photo but I''m sure your getting creamed for actually using it.</td>', 'Well yeah clear photo but I''m sure your getting creamed for actually using it.', '2007-10-14 09:27:13.000000', NULL, 1),
(4166297, 598421, 23251, '<td valign="top">A nice photo, shame about the shadows.  There is to much unused area in the crop IMHO.</td>', 'A nice photo, shame about the shadows.  There is to much unused area in the crop IMHO.', '2007-10-14 09:29:25.000000', NULL, 1),
