(4166590, 598190, 68178, '<td valign="top">Interesting perch choice :p Like the colors and depth, though there are some jagged lines in the beak and tail feathers maybe from sharpening? Still well done!</td>', 'Interesting perch choice :p Like the colors and depth, though there are some jagged lines in the beak and tail feathers maybe from sharpening? Still well done!', '2007-10-14 13:32:54.000000', NULL, 1),
(4166593, 598412, 68178, '<td valign="top">I love vultures! The DOF looks a tiny tad off, more on the neck and eyes, where the eyes and beak may have been better. Thats a tiny nitpick though, otherwise well done!</td>', 'I love vultures! The DOF looks a tiny tad off, more on the neck and eyes, where the eyes and beak may have been better. Thats a tiny nitpick though, otherwise well done!', '2007-10-14 13:34:49.000000', NULL, 1),
(4166597, 595697, 68178, '<td valign="top">Thats unique for this challenge. I like it, though I may have taken some of the color out of the wings to make it more consistent with the rest of the browns.</td>', 'Thats unique for this challenge. I like it, though I may have taken some of the color out of the wings to make it more consistent with the rest of the browns.', '2007-10-14 13:36:44.000000', NULL, 1),
(4166603, 597316, 68178, '<td valign="top">I very much like the composition and colors. The silhouettes are sharp. Well done!</td>', 'I very much like the composition and colors. The silhouettes are sharp. Well done!', '2007-10-14 13:38:27.000000', NULL, 1),
