INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4167210, 597954, 19248, '<td valign="top">Beautiful capture.  Love the backdrop, adds to the picture.</td>', 'Beautiful capture.  Love the backdrop, adds to the picture.', '2007-10-14 20:52:32.000000', NULL, 1),
(4167289, 598081, 12733, '<td valign="top">He looks like he just can''t wait for you to scratch his ears. Great capture.</td>', 'He looks like he just can''t wait for you to scratch his ears. Great capture.', '2007-10-14 21:48:20.000000', NULL, 1),
(4167293, 598021, 12733, '<td valign="top">Something about fauna as victims feels wrong to me.</td>', 'Something about fauna as victims feels wrong to me.', '2007-10-14 21:49:03.000000', NULL, 1),
(4167301, 597964, 12733, '<td valign="top">seems overbright and could be cropped tighter.</td>', 'seems overbright and could be cropped tighter.', '2007-10-14 21:51:09.000000', NULL, 1),
(4167306, 598198, 12733, '<td valign="top">Is that nut a treat you gave him for posing? Nice capture.</td>', 'Is that nut a treat you gave him for posing? Nice capture.', '2007-10-14 21:52:07.000000', NULL, 1),
(4167308, 597929, 12733, '<td valign="top">Too much Yellowstone, not enough bison.</td>', 'Too much Yellowstone, not enough bison.', '2007-10-14 21:53:32.000000', NULL, 1),
