(4167317, 595614, 12733, '<td valign="top">High key is cool, but this just about crosses the line into washed out.</td>', 'High key is cool, but this just about crosses the line into washed out.', '2007-10-14 21:56:52.000000', NULL, 1),
(4167322, 595927, 12733, '<td valign="top">That looks an awful lot like a flora to me - and that''s a different challenge.</td>', 'That looks an awful lot like a flora to me - and that''s a different challenge.', '2007-10-14 21:59:16.000000', NULL, 1),
(4167327, 597438, 12733, '<td valign="top">He is really well hidden, but he jumps out in the photo.</td>', 'He is really well hidden, but he jumps out in the photo.', '2007-10-14 22:03:31.000000', NULL, 1),
