(4169459, 596037, 76430, '<td valign="top">Ah, Cannon Beach on the Oregon coast again.  Is this <img alt="'' . substr(''//www.dpchallenge.com/images/user_icon/21.gif'', strrpos(''//www.dpchallenge.com/images/user_icon/21.gif'', ''/'') + 1) . ''" border="0" src="//www.dpchallenge.com/images/user_icon/21.gif"/> <a href="//www.dpchallenge.com/profile.php?USER_ID=20168" rel="nofollow" target="_blank">charliebaker </a>again?  Nice shot.  Nice composition, with the mist, waves and seagulls on the wet sand, but seeing some gulls flying may improve this one.</td>', 'Ah, Cannon Beach on the Oregon coast again.  Is this  charliebaker again?  Nice shot.  Nice composition, with the mist, waves and seagulls on the wet sand, but seeing some gulls flying may improve this one.', '2007-10-15 15:42:19.000000', NULL, 1),
(4169461, 597066, 76430, '<td valign="top">Nice head shot, but I''d like to see the wings also in focus.  Too shallow DOF.  I thought the left antenna was missing until I saw the blurred image of it.</td>', 'Nice head shot, but I''d like to see the wings also in focus.  Too shallow DOF.  I thought the left antenna was missing until I saw the blurred image of it.', '2007-10-15 15:45:02.000000', NULL, 1),
(4169485, 597316, 85383, '<td valign="top">Very nice composition!</td>', 'Very nice composition!', '2007-10-15 15:58:27.000000', NULL, 1),
(4169489, 595502, 85383, '<td valign="top">Would like to see the human''s face cropped out.</td>', 'Would like to see the human''s face cropped out.', '2007-10-15 15:59:18.000000', NULL, 1),
(4169490, 598150, 85383, '<td valign="top">Ok, now this is the type of photography that I love! Capturing what may be a fleeting moment.</td>', 'Ok, now this is the type of photography that I love! Capturing what may be a fleeting moment.', '2007-10-15 15:59:54.000000', NULL, 1),
