(4169495, 598061, 85383, '<td valign="top">The road is an interesting effect. Underexposed. Poor focus.</td>', 'The road is an interesting effect. Underexposed. Poor focus.', '2007-10-15 16:01:05.000000', NULL, 1),
(4169496, 597070, 85383, '<td valign="top">How sad. But a great photograph. Nice focus and composition.</td>', 'How sad. But a great photograph. Nice focus and composition.', '2007-10-15 16:01:40.000000', NULL, 1),
