(4169559, 595351, 85383, '<td valign="top">Terrible composition</td>', 'Terrible composition', '2007-10-15 16:20:15.000000', NULL, 1),
(4169575, 595351, 76430, '<td valign="top">Good shot of the landing bird, but I''m puzzled at the blank sky covering 90% of the picture.  It''s good for a negative space challenge, but I''d like to see the picture either cropped to the lower/left quadrant or, better yet, panned down and left to catch more of the tree.</td>', 'Good shot of the landing bird, but I''m puzzled at the blank sky covering 90% of the picture.  It''s good for a negative space challenge, but I''d like to see the picture either cropped to the lower/left quadrant or, better yet, panned down and left to catch more of the tree.', '2007-10-15 16:29:10.000000', NULL, 1),
(4169580, 598192, 30049, '<td valign="top">I like the colors and you caught a nice pose.  The squirrel seems a bit out of focus compared to the leaves just this side of it.</td>', 'I like the colors and you caught a nice pose.  The squirrel seems a bit out of focus compared to the leaves just this side of it.', '2007-10-15 16:33:10.000000', NULL, 1),
(4169587, 597438, 30049, '<td valign="top">Nice catch on this.  Lovely bg blur.  Wish it wasn''t quite so centered, but still one of the better ones I''ve seen thus far.</td>', 'Nice catch on this.  Lovely bg blur.  Wish it wasn''t quite so centered, but still one of the better ones I''ve seen thus far.', '2007-10-15 16:34:58.000000', NULL, 1),
(4169594, 598275, 30049, '<td valign="top">Cute bird.  This photo is substantially underexposed.  Some adjustments to your histogram/curves/levels would make this much stronger.</td>', 'Cute bird.  This photo is substantially underexposed.  Some adjustments to your histogram/curves/levels would make this much stronger.', '2007-10-15 16:36:43.000000', NULL, 1),
(4169596, 597293, 42254, '<td valign="top">Simply beautiful--great composition, color, sharp foreground, &amp; non-distracting background!</td>', 'Simply beautiful--great composition, color, sharp foreground, & non-distracting background!', '2007-10-15 16:37:43.000000', NULL, 1),
(4169598, 596687, 30049, '<td valign="top">Wonderful capture.  A polarizer could have helped to control some of the reflections.  Good catch!</td>', 'Wonderful capture.  A polarizer could have helped to control some of the reflections.  Good catch!', '2007-10-15 16:38:04.000000', NULL, 1),
(4169605, 595184, 42254, '<td valign="top">Nice action shot, but strong backlight needs fill flash to see detail; dog seems a bit blurry as well.</td>', 'Nice action shot, but strong backlight needs fill flash to see detail; dog seems a bit blurry as well.', '2007-10-15 16:39:36.000000', NULL, 1),
(4169606, 597935, 30049, '<td valign="top">A bit blurry and it looks like the image was overexposed on the birds breast, with an attempt to compensate in post-processing.  Good job to get close enough for the shot.</td>', 'A bit blurry and it looks like the image was overexposed on the birds breast, with an attempt to compensate in post-processing.  Good job to get close enough for the shot.', '2007-10-15 16:39:40.000000', NULL, 1),
(4169608, 598201, 42254, '<td valign="top">Yeah!  Unusual and strangely attractive shot!</td>', 'Yeah!  Unusual and strangely attractive shot!', '2007-10-15 16:40:10.000000', NULL, 1),
(4169609, 596578, 30049, '<td valign="top">Thank you!  Something wild and refreshing to look at besides pets and zoo shots.  I love the color and the reflections.  Nicely seen and captured.  Good luck in the challenge.</td>', 'Thank you!  Something wild and refreshing to look at besides pets and zoo shots.  I love the color and the reflections.  Nicely seen and captured.  Good luck in the challenge.', '2007-10-15 16:40:27.000000', NULL, 1),
(4169616, 596721, 30049, '<td valign="top">I like this.  The color and contrast make this jump out.  Probably a healthy dose of neat image in there, but it looks balanced enough.  :)  Good luck.</td>', 'I like this.  The color and contrast make this jump out.  Probably a healthy dose of neat image in there, but it looks balanced enough.  :)  Good luck.', '2007-10-15 16:41:42.000000', NULL, 1),
(4169619, 598018, 42254, '<td valign="top">Beautiful color &amp; position!</td>', 'Beautiful color & position!', '2007-10-15 16:41:57.000000', NULL, 1),
(4169668, 598008, 47482, '<td valign="top">great fun image</td>', 'great fun image', '2007-10-15 16:53:43.000000', NULL, 1),
(4169676, 597515, 47482, '<td valign="top">think you might have a problem with purple fringe, try this link <a href="//www.bytephoto.com/photo-editing/chromatic-aberrations.php" rel="nofollow" target="_blank">linky</a> <br/> <br/>but cute squirrel</td>', 'think you might have a problem with purple fringe, try this link linky  but cute squirrel', '2007-10-15 16:57:30.000000', NULL, 1),
