(4169683, 598033, 47482, '<td valign="top">wish the focus had been more on the bee, but great colour!</td>', 'wish the focus had been more on the bee, but great colour!', '2007-10-15 16:58:48.000000', NULL, 1),
(4169685, 596219, 47482, '<td valign="top">amazing!!, great focus!</td>', 'amazing!!, great focus!', '2007-10-15 16:59:36.000000', NULL, 1),
(4169687, 598417, 47482, '<td valign="top">this has got to be in my top 5! very emotive and great texture</td>', 'this has got to be in my top 5! very emotive and great texture', '2007-10-15 17:00:24.000000', NULL, 1),
(4169689, 595562, 47482, '<td valign="top">love the colour and detail</td>', 'love the colour and detail', '2007-10-15 17:00:56.000000', NULL, 1),
