(4169868, 595483, 76430, '<td valign="top">Basic rule, turn off your date stamp.  Besides identifying the shot outside the challenge date range it is very aesthetically displeasing.  Otherwise it''s a good shot.  I was thinking it was a white wolf at first glance until I saw the collar.</td>', 'Basic rule, turn off your date stamp.  Besides identifying the shot outside the challenge date range it is very aesthetically displeasing.  Otherwise it''s a good shot.  I was thinking it was a white wolf at first glance until I saw the collar.', '2007-10-15 18:18:58.000000', NULL, 1),
(4169869, 597503, 73601, '<td valign="top">nice goat portrait, crisp focus, nice crop</td>', 'nice goat portrait, crisp focus, nice crop', '2007-10-15 18:19:15.000000', NULL, 1),
(4169872, 596080, 73601, '<td valign="top">focus is good, nice composition</td>', 'focus is good, nice composition', '2007-10-15 18:19:40.000000', NULL, 1),
(4169878, 597692, 76430, '<td valign="top">Not sharp enough, probably caused by long handheld exposure.  Some diffused flash would help a lot.</td>', 'Not sharp enough, probably caused by long handheld exposure.  Some diffused flash would help a lot.', '2007-10-15 18:21:29.000000', NULL, 1),
(4169883, 595697, 76430, '<td valign="top">Great job with the widespread wings and silhouette.  Somehow I doubt the title, but a great shot.</td>', 'Great job with the widespread wings and silhouette.  Somehow I doubt the title, but a great shot.', '2007-10-15 18:22:53.000000', NULL, 1),
(4169890, 597929, 76430, '<td valign="top">The Bison are very small.  I think cropping down to the river and bison and a little of the snow above it would help this.</td>', 'The Bison are very small.  I think cropping down to the river and bison and a little of the snow above it would help this.', '2007-10-15 18:29:07.000000', NULL, 1),
(4169892, 596166, 76430, '<td valign="top">Great leaf and dewey web shot as well as bokeh, but where is the fauna?</td>', 'Great leaf and dewey web shot as well as bokeh, but where is the fauna?', '2007-10-15 18:30:01.000000', NULL, 1),
(4169962, 597314, 76430, '<td valign="top">I wish the antlers were all there.  Great shot otherwise.</td>', 'I wish the antlers were all there.  Great shot otherwise.', '2007-10-15 18:59:33.000000', NULL, 1),
(4169967, 597508, 76430, '<td valign="top">It looks like the hummingbird caught a bee, but since they drink nectar I''ll assume they''re at different distances.  Still a good capture.  Nice sharp shot.</td>', 'It looks like the hummingbird caught a bee, but since they drink nectar I''ll assume they''re at different distances.  Still a good capture.  Nice sharp shot.', '2007-10-15 19:01:41.000000', NULL, 1),
(4169990, 597316, 83858, '<td valign="top">I love it!</td>', 'I love it!', '2007-10-15 19:15:13.000000', NULL, 1),
(4169991, 597258, 40430, '<td valign="top">really nice image. the only quibble might be not enough room on the R side of the image between the horse and the edge of the image.  great lighting.</td>', 'really nice image. the only quibble might be not enough room on the R side of the image between the horse and the edge of the image.  great lighting.', '2007-10-15 19:15:17.000000', NULL, 1),
(4169995, 595307, 40430, '<td valign="top">a bit blurry- nice color</td>', 'a bit blurry- nice color', '2007-10-15 19:16:57.000000', NULL, 1),
(4169996, 595990, 40430, '<td valign="top">very nice lighting</td>', 'very nice lighting', '2007-10-15 19:17:58.000000', NULL, 1),
(4169998, 597314, 40430, '<td valign="top">I would like to have seen more of the antlers.  nice lighting and very good clarity</td>', 'I would like to have seen more of the antlers.  nice lighting and very good clarity', '2007-10-15 19:18:45.000000', NULL, 1),
(4170002, 598169, 76430, '<td valign="top">Ooh, the poor widdle mouse.  Good capture but you are going to get a lot of comments about the brutal scene.</td>', 'Ooh, the poor widdle mouse.  Good capture but you are going to get a lot of comments about the brutal scene.', '2007-10-15 19:22:32.000000', NULL, 1),
(4170005, 595502, 76430, '<td valign="top">I believe this is the boss.  The gray one being held behind looks intimidated.  I''d prefer not to see the guy holding the gray cat.</td>', 'I believe this is the boss.  The gray one being held behind looks intimidated.  I''d prefer not to see the guy holding the gray cat.', '2007-10-15 19:23:52.000000', NULL, 1),
(4170009, 597277, 40430, '<td valign="top">nice sharpness</td>', 'nice sharpness', '2007-10-15 19:27:24.000000', NULL, 1),
(4170125, 595309, 76430, '<td valign="top">Is this for real or a model in a museum?  Good capture.</td>', 'Is this for real or a model in a museum?  Good capture.', '2007-10-15 20:32:16.000000', NULL, 1),
(4170130, 598061, 76430, '<td valign="top">I would have cropped out the top with the white lines and some of the left and right to make it a good size and better deer detail.  Otherwise a pretty good capture.</td>', 'I would have cropped out the top with the white lines and some of the left and right to make it a good size and better deer detail.  Otherwise a pretty good capture.', '2007-10-15 20:33:41.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4170139, 598419, 76430, '<td valign="top">It would have been great if you could have gotten a bird nose to nose with the rubber duckie.  Maybe if you could have moved down near the ground and left it would have appeared the small bird was talking to the duck.</td>', 'It would have been great if you could have gotten a bird nose to nose with the rubber duckie.  Maybe if you could have moved down near the ground and left it would have appeared the small bird was talking to the duck.', '2007-10-15 20:37:20.000000', NULL, 1),
(4170148, 598127, 76430, '<td valign="top">Nice picture except for the bridge in the background and the water outlet under the beak.  A slightly different vantage point would have been nice.</td>', 'Nice picture except for the bridge in the background and the water outlet under the beak.  A slightly different vantage point would have been nice.', '2007-10-15 20:40:48.000000', NULL, 1),
(4170152, 598189, 76430, '<td valign="top">This looks like an underwater shot, or maybe through an aquarium wall.  Nice one.</td>', 'This looks like an underwater shot, or maybe through an aquarium wall.  Nice one.', '2007-10-15 20:42:59.000000', NULL, 1),
(4170162, 595614, 76430, '<td valign="top">Maybe it''s high key, but it looks too washed out for me.  It loses the detail.</td>', 'Maybe it''s high key, but it looks too washed out for me.  It loses the detail.', '2007-10-15 20:47:21.000000', NULL, 1),
(4170187, 595099, 76430, '<td valign="top">Pretty poor resolution on this one.  Also the camera flash causes harsh shadows.  It meets the challenge though.</td>', 'Pretty poor resolution on this one.  Also the camera flash causes harsh shadows.  It meets the challenge though.', '2007-10-15 21:02:59.000000', NULL, 1),
(4170194, 595927, 76430, '<td valign="top">This looks more flora than fauna.  Did you get it in the wrong challenge?  Nice detail on the flower.</td>', 'This looks more flora than fauna.  Did you get it in the wrong challenge?  Nice detail on the flower.', '2007-10-15 21:05:37.000000', NULL, 1),
(4170463, 595927, 83395, '<td valign="top">I thought that fauna typically referred to animal life.  Perhaps, you submitted to the wrong challenge and should be in flora.  I would have given you an 8 in flora.  I love the reflected image.</td>', 'I thought that fauna typically referred to animal life.  Perhaps, you submitted to the wrong challenge and should be in flora.  I would have given you an 8 in flora.  I love the reflected image.', '2007-10-15 23:02:24.000000', NULL, 1),
(4170504, 598142, 66384, '<td valign="top">Love the water background.</td>', 'Love the water background.', '2007-10-15 23:11:00.000000', NULL, 1),
(4170523, 597692, 66384, '<td valign="top">Focus</td>', 'Focus', '2007-10-15 23:15:51.000000', NULL, 1),
(4170548, 598044, 66384, '<td valign="top">Very touching photo. Wish there wasn''t a wire in the shot.</td>', 'Very touching photo. Wish there wasn''t a wire in the shot.', '2007-10-15 23:22:05.000000', NULL, 1),
(4170559, 598158, 66384, '<td valign="top">Rather sad expression. Beautiful detail.</td>', 'Rather sad expression. Beautiful detail.', '2007-10-15 23:24:23.000000', NULL, 1),
(4170571, 597279, 66384, '<td valign="top">Beautiful detail, color, light, and composition. 10</td>', 'Beautiful detail, color, light, and composition. 10', '2007-10-15 23:27:39.000000', NULL, 1),
(4170581, 597371, 85423, '<td valign="top">I love the colours of this shot.</td>', 'I love the colours of this shot.', '2007-10-15 23:31:22.000000', NULL, 1),
(4170582, 596790, 85423, '<td valign="top">Great catch!</td>', 'Great catch!', '2007-10-15 23:31:36.000000', NULL, 1),
(4170583, 597438, 85423, '<td valign="top">great colour!</td>', 'great colour!', '2007-10-15 23:31:49.000000', NULL, 1),
(4170587, 597851, 66384, '<td valign="top">Love the angle you took this from. Beautiful shot and adorable subject.</td>', 'Love the angle you took this from. Beautiful shot and adorable subject.', '2007-10-15 23:32:43.000000', NULL, 1),
(4170601, 597371, 66384, '<td valign="top">Oh, this is gorgeous. Beautiful focus and DOF, and the background really complements the subject.</td>', 'Oh, this is gorgeous. Beautiful focus and DOF, and the background really complements the subject.', '2007-10-15 23:38:41.000000', NULL, 1),
(4170618, 595365, 66384, '<td valign="top">Yikes, amazing color and clarity.</td>', 'Yikes, amazing color and clarity.', '2007-10-15 23:41:56.000000', NULL, 1),
(4170631, 598170, 66384, '<td valign="top">I love the soft texture you captured here. Very nice image.</td>', 'I love the soft texture you captured here. Very nice image.', '2007-10-15 23:45:12.000000', NULL, 1),
(4170640, 595351, 66384, '<td valign="top">The detail of the feathers has been lost because of the harsh light, but this is a nice action shot. I think a tighter crop would improve the image.</td>', 'The detail of the feathers has been lost because of the harsh light, but this is a nice action shot. I think a tighter crop would improve the image.', '2007-10-15 23:48:52.000000', NULL, 1),
(4170642, 598320, 66384, '<td valign="top">I like the background a lot.</td>', 'I like the background a lot.', '2007-10-15 23:50:08.000000', NULL, 1),
