INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4172606, 597371, 54446, '<td valign="top">Just gorgeous.  Great capture!  (9)</td>', 'Just gorgeous.  Great capture!  (9)', '2007-10-16 19:59:28.000000', NULL, 1),
(4172608, 598217, 54446, '<td valign="top">Very cool!  One of my favorites in this challenge!  (9)</td>', 'Very cool!  One of my favorites in this challenge!  (9)', '2007-10-16 19:59:50.000000', NULL, 1),
(4172637, 597258, 81216, '<td valign="top">Nice shot!</td>', 'Nice shot!', '2007-10-16 20:18:46.000000', NULL, 1),
(4172791, 598258, 18197, '<td valign="top">Nice looking models. Good colors. Well focused with pleasant DOF. But IMO you''ve gone a little too far editing the girl''s eyes.</td>', 'Nice looking models. Good colors. Well focused with pleasant DOF. But IMO you''ve gone a little too far editing the girl''s eyes.', '2007-10-16 21:55:38.000000', NULL, 1),
(4172792, 595927, 18197, '<td valign="top">Wrong challenge I think.</td>', 'Wrong challenge I think.', '2007-10-16 21:56:16.000000', NULL, 1),
(4172801, 598170, 42254, '<td valign="top">Fantastic colors &amp; appeal; sharp foreground.  Too bad there is that Bright background.</td>', 'Fantastic colors & appeal; sharp foreground.  Too bad there is that Bright background.', '2007-10-16 22:00:22.000000', NULL, 1),
(4172804, 596208, 18197, '<td valign="top">I have photographed this sculpture (or a similar one perhaps by the same sculpter) many times trying to get it just right. And I''ve visited the Palazzo Vechio many more times, just to look at it. Well done. IMO, it''s a little dark on my calibrated monitor.</td>', 'I have photographed this sculpture (or a similar one perhaps by the same sculpter) many times trying to get it just right. And I''ve visited the Palazzo Vechio many more times, just to look at it. Well done. IMO, it''s a little dark on my calibrated monitor.', '2007-10-16 22:00:45.000000', NULL, 1),
(4172809, 596522, 18197, '<td valign="top">Wonderful capture. I like the subject and the pose/composition/crop. A little more mid-tone contrast would help this in my opinion. And if I were editing it, I might boost the saturation just a little. Still well done and I''m giving a good score.</td>', 'Wonderful capture. I like the subject and the pose/composition/crop. A little more mid-tone contrast would help this in my opinion. And if I were editing it, I might boost the saturation just a little. Still well done and I''m giving a good score.', '2007-10-16 22:02:57.000000', NULL, 1),
(4172862, 598169, 85422, '<td valign="top">Wow...technically this is a nice picture with decent composition and exposure.  However, you should caution viewers against enjoying this image just before or just after eating.</td>', 'Wow...technically this is a nice picture with decent composition and exposure.  However, you should caution viewers against enjoying this image just before or just after eating.', '2007-10-16 22:32:13.000000', NULL, 1),
(4172865, 598028, 42254, '<td valign="top">Great shot--expression, contrast with sky, composition!</td>', 'Great shot--expression, contrast with sky, composition!', '2007-10-16 22:33:00.000000', NULL, 1),
(4172866, 598263, 85422, '<td valign="top">Probably be better if it was bigger.</td>', 'Probably be better if it was bigger.', '2007-10-16 22:33:05.000000', NULL, 1),
(4172869, 598258, 85422, '<td valign="top">Need a tripod or mirror lock-up to prevent the slight motion blur.  The lighting is nice.</td>', 'Need a tripod or mirror lock-up to prevent the slight motion blur.  The lighting is nice.', '2007-10-16 22:33:56.000000', NULL, 1),
(4172873, 598125, 85422, '<td valign="top">A tighter crop would be better</td>', 'A tighter crop would be better', '2007-10-16 22:34:32.000000', NULL, 1),
(4172874, 598226, 42254, '<td valign="top">Great closeup &amp; detail.</td>', 'Great closeup & detail.', '2007-10-16 22:34:50.000000', NULL, 1),
(4172876, 598300, 85422, '<td valign="top">Focus, exposure, composition are all off in this image.</td>', 'Focus, exposure, composition are all off in this image.', '2007-10-16 22:34:56.000000', NULL, 1),
(4172878, 597014, 85422, '<td valign="top">I like the very slight motion blur seen in the legs.  The image would be even better if this was even more severe with the head remaining still.</td>', 'I like the very slight motion blur seen in the legs.  The image would be even better if this was even more severe with the head remaining still.', '2007-10-16 22:36:02.000000', NULL, 1),
(4172880, 595170, 42254, '<td valign="top">Lovely - just a little bright in sky.</td>', 'Lovely - just a little bright in sky.', '2007-10-16 22:36:19.000000', NULL, 1),
(4172884, 596037, 85422, '<td valign="top">The arrangement of birds is the weak link here.  Nice landscape though...</td>', 'The arrangement of birds is the weak link here.  Nice landscape though...', '2007-10-16 22:36:50.000000', NULL, 1),
(4172885, 596752, 42254, '<td valign="top">Nice detail and a beautiful background!</td>', 'Nice detail and a beautiful background!', '2007-10-16 22:37:04.000000', NULL, 1),
(4172887, 598028, 85422, '<td valign="top">Too bad giraffes are so ugly up close.  Nice composition, color and exposure.</td>', 'Too bad giraffes are so ugly up close.  Nice composition, color and exposure.', '2007-10-16 22:37:31.000000', NULL, 1),
(4172888, 597314, 85422, '<td valign="top">Slightly too tight a crop here.</td>', 'Slightly too tight a crop here.', '2007-10-16 22:37:43.000000', NULL, 1),
(4172890, 598190, 42254, '<td valign="top">Great shot of a beautiful bird.</td>', 'Great shot of a beautiful bird.', '2007-10-16 22:38:24.000000', NULL, 1),
(4172891, 595927, 85422, '<td valign="top">Fauna, huh...very nice image otherwise.</td>', 'Fauna, huh...very nice image otherwise.', '2007-10-16 22:38:42.000000', NULL, 1),
