(4178427, 597438, 30049, '<td valign="top">You did a very nice job with this photo.  I''m surprised at the final placing.  Certainly a "keeper" in my book.  :-)</td>', 'You did a very nice job with this photo.  I''m surprised at the final placing.  Certainly a "keeper" in my book.  :-)', '2007-10-18 13:31:01.000000', NULL, 0),
